/* ================= TIN HỌC 9 ================= */
function tin9CountIF() {
  var scores = [], i, k = pick([5, 6, 7]);
  for (i = 0; i < 8; i++) scores.push(rand(3, 10));
  var cnt = scores.filter(function (x) { return x > k; }).length;
  return numMCQ6("Bảng tính có cột điểm B2:B9 lần lượt là: " + scores.join(", ") + ". Hàm =COUNTIF(B2:B9;\">" + k + "\") đếm số ô thỏa điều kiện. Kết quả của hàm là bao nhiêu?", scores.join(", "), cnt, "COUNTIF đếm số ô trong vùng thỏa điều kiện \">" + k + "\": có " + cnt + " ô có giá trị lớn hơn " + k + ".", 2);
}
function tin9SumIF() {
  var cats = ["Bút", "Vở", "Bút", "Thước", "Vở", "Bút"];
  var vals = cats.map(function () { return rand(2, 12) * 1000; });
  var target = pick(["Bút", "Vở"]);
  var sum = 0; cats.forEach(function (c, i) { if (c === target) sum += vals[i]; });
  var rows = cats.map(function (c, i) { return c + ": " + fmtN(vals[i]); }).join("; ");
  return numMCQ6("Bảng chi tiêu có các dòng (Mặt hàng: Số tiền): " + rows + ". Hàm =SUMIF tra theo mặt hàng \"" + target + "\" cộng tổng tiền của mặt hàng đó. Kết quả là bao nhiêu đồng?", rows, sum, "SUMIF cộng các ô số tiền tại những dòng có mặt hàng là \"" + target + "\": tổng = " + fmtN(sum) + " đồng.", 3000);
}
function tin9IF() {
  var scores = [], i;
  for (i = 0; i < 8; i++) scores.push(rand(3, 10));
  var cnt = scores.filter(function (x) { return x >= 5; }).length;
  return numMCQ6("Áp dụng công thức =IF(điểm>=5;\"Đạt\";\"Chưa đạt\") cho 8 học sinh có điểm: " + scores.join(", ") + ". Có bao nhiêu học sinh được xếp loại \"Đạt\"?", scores.join(", "), cnt, "Hàm IF trả về \"Đạt\" khi điểm >= 5. Đếm trong dãy có " + cnt + " điểm thỏa mãn.", 2);
}
